layer.css:
[data-ryt="footer"] { color: rgb(17, 17, 17); background-color: var(--ryt-bg); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: rgb(0, 0, 238); border-radius: 0px; font-family: "Times New Roman"; font-size: 16px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 238); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-muted); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: "Times New Roman"; font-size: 40px; font-weight: 700; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
